1790	function topoSort(nodes, edges) {
1791	  const inDegree = {};
1792	  const adj = {};
1793	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
1794	  for (const e of edges) {
1795	    adj[e.source].push(e.target);
1796	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
1797	  }
1798	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
1799	  const order = [];
1800	  while (queue.length) {
1801	    const id = queue.shift();
1802	    order.push(id);
1803	    for (const next of adj[id]) {
1804	      inDegree[next]--;
1805	      if (inDegree[next] === 0) queue.push(next);
1806	    }
1807	  }
1808	  return order;
1809	}
